import{_ as t,o as a,c as o,l as r,t as s,N as i}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"localedef | x-cmd man (man1) | compile locale definition files","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | localedef - compile locale definition files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"localedef | x-cmd man (man1) | compile locale definition files"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | localedef - compile locale definition files"}]]},"headers":[],"params":{"isMan":true,"man":"localedef","category":"man1","desc":"compile locale definition files"},"relativePath":"man1/localedef.md","filePath":"man1/localedef.md"}'),n={name:"man1/localedef.md"},d={class:"visually-hidden"},l=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>localedef - compile locale definition files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>localedef</strong> [<em>options</em>] <em>outputpath</em> <strong>localedef</strong><strong>--add-to-archive</strong> [<em>options</em>] <em>compiledpath</em> <strong>localedef</strong><strong>--delete-from-archive</strong> [<em>options</em>] <em>localename</em> ... <strong>localedef</strong><strong>--list-archive</strong> [<em>options</em>] <strong>localedef</strong> <strong>--help</strong><strong>localedef</strong> <strong>--usage</strong> <strong>localedef</strong> <strong>--version</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>localedef</strong> program reads the indicated <em>charmap</em> and <em>input</em> files, compiles them to a binary form quickly usable by the locale functions in the C library (<strong>setlocale</strong>(3), <strong>localeconv</strong>(3), etc.), and places the output in <em>outputpath</em>.</p><p>The <em>outputpath</em> argument is interpreted as follows:</p><ul><li><p>If <em>outputpath</em> contains a slash character (&#39;/&#39;), it is interpreted as the name of the directory where the output definitions are to be stored. In this case, there is a separate output file for each locale category (<em>LC_TIME</em>, <em>LC_NUMERIC</em>, and so on).</p></li><li><p>If the <strong>--no-archive</strong> option is used, <em>outputpath</em> is the name of a subdirectory in <em>/usr/lib/locale</em> where per-category compiled files are placed.</p></li><li><p>Otherwise, <em>outputpath</em> is the name of a locale and the compiled locale data is added to the archive file <em>/usr/lib/locale/locale-archive</em>. A locale archive is a memory-mapped file which contains all the system-provided locales; it is used by all localized programs when the environment variable <strong>LOCPATH</strong> is not set.</p></li></ul><p>In any case, <strong>localedef</strong> aborts if the directory in which it tries to write locale files has not already been created.</p><p>If no <em>charmapfile</em> is given, the value <em>ANSI_X3.4-1968</em> (for ASCII) is used by default. If no <em>inputfile</em> is given, or if it is given as a dash (-), <strong>localedef</strong> reads from standard input.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><h3 id="operation-selection-options" tabindex="-1">Operation-selection options <a class="header-anchor" href="#operation-selection-options" aria-label="Permalink to &quot;Operation-selection options&quot;">​</a></h3><p>A few options direct <strong>localedef</strong> to do something other than compile locale definitions. Only one of these options should be used at a time.</p><dl><dt><strong>--add-to-archive</strong></dt><dd>Add the <em>compiledpath</em> directories to the locale archive file. The directories should have been created by previous runs of <strong>localedef</strong>, using <strong>--no-archive</strong>.</dd><dt><strong>--delete-from-archive</strong></dt><dd>Delete the named locales from the locale archive file.</dd><dt><strong>--list-archive</strong></dt><dd>List the locales contained in the locale archive file.</dd></dl><h3 id="other-options" tabindex="-1">Other options <a class="header-anchor" href="#other-options" aria-label="Permalink to &quot;Other options&quot;">​</a></h3><p>Some of the following options are sensible only for certain operations; generally, it should be self-evident which ones. Notice that <strong>-f</strong> and <strong>-c</strong> are reversed from what you might expect; that is, <strong>-f</strong> is not the same as <strong>--force</strong>.</p><dl><dt><strong>-f</strong> * charmapfile** <em>, --charmap=</em>* <em>charmapfile</em></dt><dd>Specify the file that defines the character set that is used by the input file. If <em>charmapfile</em> contains a slash character (&#39;/&#39;), it is interpreted as the name of the character map. Otherwise, the file is sought in the current directory and the default directory for character maps. If the environment variable <strong>I18NPATH</strong> is set, <em>$I18NPATH/charmaps/</em> and <em>$I18NPATH/</em> are also searched after the current directory. The default directory for character maps is printed by <strong>localedef --help</strong>.</dd><dt><strong>-i</strong> * inputfile** <em>, --inputfile=</em>* <em>inputfile</em></dt><dd>Specify the locale definition file to compile. The file is sought in the current directory and the default directory for locale definition files. If the environment variable <strong>I18NPATH</strong> is set, <em>$I18NPATH/locales/</em> and <em>$I18NPATH</em> are also searched after the current directory. The default directory for locale definition files is printed by <strong>localedef --help</strong>.</dd><dt><strong>-u</strong> * repertoirefile** <em>, --repertoire-map=</em>* <em>repertoirefile</em></dt><dd>Read mappings from symbolic names to Unicode code points from <em>repertoirefile</em>. If <em>repertoirefile</em> contains a slash character (&#39;/&#39;), it is interpreted as the pathname of the repertoire map. Otherwise, the file is sought in the current directory and the default directory for repertoire maps. If the environment variable <strong>I18NPATH</strong> is set, <em>$I18NPATH/repertoiremaps/</em> and <em>$I18NPATH</em> are also searched after the current directory. The default directory for repertoire maps is printed by <strong>localedef --help</strong>.</dd><dt><strong>-A</strong> * aliasfile** <em>, --alias-file=</em>* <em>aliasfile</em></dt><dd>Use <em>aliasfile</em> to look up aliases for locale names. There is no default aliases file.</dd><dt><strong>--force</strong> <br> <strong>-c</strong></dt><dd>Write the output files even if warnings were generated about the input file.</dd><dt><strong>--verbose</strong> <br> <strong>-v</strong></dt><dd>Generate extra warnings about errors that are normally ignored.</dd><dt><strong>--big-endian</strong></dt><dd>Generate big-endian output.</dd><dt><strong>--little-endian</strong></dt><dd>Generate little-endian output.</dd><dt><strong>--no-archive</strong></dt><dd>Do not use the locale archive file, instead create <em>outputpath</em> as a subdirectory in the same directory as the locale archive file, and create separate output files for locale categories in it. This is helpful to prevent system locale archive updates from overwriting custom locales created with <strong>localedef</strong>.</dd><dt><strong>--no-hard-links</strong></dt><dd>Do not create hard links between installed locales.</dd><dt><strong>--no-warnings=</strong> <em>warnings</em></dt><dd>Comma-separated list of warnings to disable. Supported warnings are <em>ascii</em> and <em>intcurrsym</em>.</dd><dt><strong>--posix</strong></dt><dd>Conform strictly to POSIX. Implies <strong>--verbose</strong>. This option currently has no other effect. POSIX conformance is assumed if the environment variable <strong>POSIXLY_CORRECT</strong> is set.</dd><dt><strong>--prefix=</strong> <em>pathname</em></dt><dd>Set the prefix to be prepended to the full archive pathname. By default, the prefix is empty. Setting the prefix to <em>foo</em>, the archive would be placed in <em>foo/usr/lib/locale/locale-archive</em>.</dd><dt><strong>--quiet</strong></dt><dd>Suppress all notifications and warnings, and report only fatal errors.</dd><dt><strong>--replace</strong></dt><dd>Replace a locale in the locale archive file. Without this option, if the locale is in the archive file already, an error occurs.</dd><dt><strong>--warnings=</strong> <em>warnings</em></dt><dd>Comma-separated list of warnings to enable. Supported warnings are <em>ascii</em> and <em>intcurrsym</em>.</dd><dt><strong>--help</strong> <br> <strong>-?</strong></dt><dd>Print a usage summary and exit. Also prints the default paths used by <strong>localedef</strong>.</dd><dt><strong>--usage</strong></dt><dd>Print a short usage summary and exit.</dd><dt><strong>--version</strong> <br> <strong>-V</strong></dt><dd>Print the version number, license, and disclaimer of warranty for <strong>localedef</strong>.</dd></dl><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>One of the following exit values can be returned by <strong>localedef</strong>:</p><dl><dt><strong>0</strong></dt><dd>Command completed successfully.</dd><dt><strong>1</strong></dt><dd>Warnings or errors occurred, output files were written.</dd><dt><strong>4</strong></dt><dd>Errors encountered, no output created.</dd></dl><h2 id="environment" tabindex="-1">ENVIRONMENT <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;ENVIRONMENT&quot;">​</a></h2><dl><dt><strong>POSIXLY_CORRECT</strong></dt><dd>The <strong>--posix</strong> flag is assumed if this environment variable is set.</dd><dt><strong>I18NPATH</strong></dt><dd>A colon-separated list of search directories for files.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/usr/share/i18n/charmaps</em></dt><dd>Usual default character map path.</dd><dt><em>/usr/share/i18n/locales</em></dt><dd>Usual default path for locale definition files.</dd><dt><em>/usr/share/i18n/repertoiremaps</em></dt><dd>Usual default repertoire map path.</dd><dt><em>/usr/lib/locale/locale-archive</em></dt><dd>Usual default locale archive location.</dd><dt><em>/usr/lib/locale</em></dt><dd>Usual default path for compiled individual locale data files.</dd><dt><em>outputpath/LC_ADDRESS</em></dt><dd>An output file that contains information about formatting of addresses and geography-related items.</dd><dt><em>outputpath/LC_COLLATE</em></dt><dd>An output file that contains information about the rules for comparing strings.</dd><dt><em>outputpath/LC_CTYPE</em></dt><dd>An output file that contains information about character classes.</dd><dt><em>outputpath/LC_IDENTIFICATION</em></dt><dd>An output file that contains metadata about the locale.</dd><dt><em>outputpath/LC_MEASUREMENT</em></dt><dd>An output file that contains information about locale measurements (metric versus US customary).</dd><dt><em>outputpath/LC_MESSAGES/SYS_LC_MESSAGES</em></dt><dd>An output file that contains information about the language messages should be printed in, and what an affirmative or negative answer looks like.</dd><dt><em>outputpath/LC_MONETARY</em></dt><dd>An output file that contains information about formatting of monetary values.</dd><dt><em>outputpath/LC_NAME</em></dt><dd>An output file that contains information about salutations for persons.</dd><dt><em>outputpath/LC_NUMERIC</em></dt><dd>An output file that contains information about formatting of nonmonetary numeric values.</dd><dt><em>outputpath/LC_PAPER</em></dt><dd>An output file that contains information about settings related to standard paper size.</dd><dt><em>outputpath/LC_TELEPHONE</em></dt><dd>An output file that contains information about formats to be used with telephone services.</dd><dt><em>outputpath/LC_TIME</em></dt><dd>An output file that contains information about formatting of data and time values.</dd></dl><h2 id="standards" tabindex="-1">STANDARDS <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;STANDARDS&quot;">​</a></h2><p>POSIX.1-2008.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Compile the locale files for Finnish in the UTF-8 character set and add it to the default locale archive with the name <strong>fi_FI.UTF-8</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localedef</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fi_FI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fi_FI.UTF-8</span></span></code></pre></div><p>The next example does the same thing, but generates files into the <em>fi_FI.UTF-8</em> directory which can then be used by programs when the environment variable <strong>LOCPATH</strong> is set to the current directory (note that the last argument must contain a slash):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localedef</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fi_FI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./fi_FI.UTF-8</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>locale</strong>(1), <strong>charmap</strong>(5), <strong>locale</strong>(5), <strong>repertoiremap</strong>(5), <strong>locale</strong>(7)</p>',33);function h(e,c,m,p,f,u){return a(),o("div",null,[r("h1",d,s(e.$params.man),1),l])}const y=t(n,[["render",h]]);export{b as __pageData,y as default};
